mapper.select:
SELECT  FROM reconcile_diff

ORDER BY reconcile_date DESC, created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.sql:
WHERE platform_subsidy_due > 0.00
  AND status IN ('SPLIT_SUCCEEDED','REVERSING','PARTIALLY_REVERSED','REVERSED','REVERSE_FAILED')

  AND merchant_id=#{merchantId}


  AND updated_at >= #{fromAt}


  AND updated_at < #{toAtExclusive}

mapper.select:
SELECT 
FROM settlement_instruction
WHERE merchant_no=#{merchantNo}
  AND (
    (sent_at >= #{dayStartUtc} AND sent_at < #{dayEndUtcExclusive})
    OR (sent_at IS NULL AND created_at >= #{dayStartUtc} AND created_at < #{dayEndUtcExclusive})
    OR finish_date=#{reconcileDate}
  )
ORDER BY id ASC

SELECT id,settlement_order_id,status,sent_at,created_at,updated_at
FROM settlement_instruction
WHERE status IN ('SENT','PROCESSING')
  AND updated_at <= #{cutoff}
ORDER BY updated_at ASC, id ASC
LIMIT #{limit}
